export type SdkVersion = "sdk47" | "sdk53";
let activeVersion: SdkVersion = "sdk47";
const chainSdkVersions = new Map<string, SdkVersion>();
const endpointSdkVersions = new Map<string, SdkVersion>();
const logSdk = (...args: unknown[]) => {
  // Enable via globalThis.COSMES_DEBUG_SDK = true
  if ((globalThis as { COSMES_DEBUG_SDK?: boolean }).COSMES_DEBUG_SDK) {
    console.log("[cosmes/sdk]", ...args);
  }
};

export const setActiveSdkVersion = (version: SdkVersion) => {
  if (activeVersion === version) {
    return;
  }
  logSdk("setActiveSdkVersion", { from: activeVersion, to: version });
  activeVersion = version;
  applyActive();
};
export const getActiveSdkVersion = () => activeVersion;
export const setChainSdkVersion = (chainId: string, version: SdkVersion) => {
  logSdk("setChainSdkVersion", { chainId, version });
  chainSdkVersions.set(chainId, version);
};
export const getChainSdkVersion = (chainId: string) =>
  chainSdkVersions.get(chainId) ?? activeVersion;
export const useChainSdkVersion = (chainId: string) =>
  setActiveSdkVersion(getChainSdkVersion(chainId));
export const setEndpointSdkVersion = (endpoint: string, version: SdkVersion) => {
  logSdk("setEndpointSdkVersion", { endpoint, version });
  endpointSdkVersions.set(endpoint, version);
};
export const getEndpointSdkVersion = (endpoint: string) =>
  endpointSdkVersions.get(endpoint) ?? activeVersion;
export const useEndpointSdkVersion = (endpoint: string) =>
  setActiveSdkVersion(getEndpointSdkVersion(endpoint));

